package com.tuap.backend.auth;
import java.net.URLEncoder; import java.nio.charset.StandardCharsets; import org.springframework.boot.autoconfigure.condition.ConditionalOnProperty; import org.springframework.stereotype.Component; import com.tuap.backend.config.EmailProperties;
@Component @ConditionalOnProperty(prefix="app.email",name="enabled",havingValue="true") public class EmailPasswordResetNotifier implements PasswordResetNotifier { private final EmailService email; private final EmailProperties properties; public EmailPasswordResetNotifier(EmailService e,EmailProperties p){email=e;properties=p;} public void notifyReset(AuthenticatedUser user,String token){String url=properties.getPasswordResetUrl()+"?token="+URLEncoder.encode(token,StandardCharsets.UTF_8);String html="<p>Has solicitado restablecer tu contraseña de NextFit.</p><p><a href=\""+url+"\">Restablecer contraseña</a></p><p>Este enlace caduca en 30 minutos. Si no lo solicitaste, ignora este mensaje.</p>";email.send(user.email(),"Restablece tu contraseña de NextFit",html);} }
